/** Evenly spaced hues, so every pair stays distinct however many there are. */
const colour = (i: number) => `hsl(${(i * 137.508) % 360} 70% 50%)`;

export const PACK: Level[] = PACK_DOTS.map(({ name, size, dots }) => ({
  name,
  size,
  pairs: dots.map(([r1, c1, r2, c2], i): Pair => ({ id: `p${i}`, color: colour(i), a: [r1, c1], b: [r2, c2] })),
}));
